// Generated by Automated Quality Gate; review before merging.
const math = require('../../src/math');

describe('math utility functions', () => {
  describe('validation logic', () => {
    test('should throw TypeError for non-number inputs', () => {
      expect(() => math.add('1', 2)).toThrow(TypeError);
      expect(() => math.add(null, 2)).toThrow("Inputs must be valid numbers");
      expect(() => math.add(1, undefined)).toThrow("Inputs must be valid numbers");
    });

    test('should throw TypeError for NaN', () => {
      expect(() => math.add(NaN, 5)).toThrow("Inputs must be valid numbers");
    });

    test('should throw TypeError for Infinity', () => {
      expect(() => math.add(Infinity, 1)).toThrow("Inputs must be finite numbers");
      expect(() => math.add(1, -Infinity)).toThrow("Inputs must be finite numbers");
    });
  });

  describe('add', () => {
    test('should return correct sum', () => {
      expect(math.add(2, 3)).toBe(5);
      expect(math.add(-1, -1)).toBe(-2);
    });
  });

  describe('subtract', () => {
    test('should subtract and normalize -0', () => {
      expect(math.subtract(5, 5)).toBe(0);
      expect(Object.is(math.subtract(5, 5), -0)).toBe(false);
    });
  });

  describe('multiply', () => {
    test('should multiply correctly', () => {
      expect(math.multiply(2, -3)).toBe(-6);
      expect(math.multiply(0, 5)).toBe(0);
    });
  });

  describe('divide', () => {
    test('should divide correctly', () => {
      expect(math.divide(10, 2)).toBe(5);
    });

    test('should throw error on division by zero', () => {
      expect(() => math.divide(10, 0)).toThrow("Cannot divide by zero");
      expect(() => math.divide(10, -0)).toThrow("Cannot divide by zero");
    });
  });

  describe('calculatePercentage', () => {
    test('should calculate percentage', () => {
      expect(math.calculatePercentage(50, 200)).toBe(25);
    });

    test('should return 0 when total is 0', () => {
      expect(math.calculatePercentage(10, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should perform mathematical modulo', () => {
      expect(math.modulo(7, 4)).toBe(3);
      expect(math.modulo(-7, 4)).toBe(1);
      expect(math.modulo(5.5, 2)).toBeCloseTo(1.5);
    });

    test('should throw error on modulo by zero', () => {
      expect(() => math.modulo(10, 0)).toThrow("Cannot modulo by zero");
    });
  });

  describe('absoluteDifference', () => {
    test('should return absolute difference', () => {
      expect(math.absoluteDifference(10, 5)).toBe(5);
      expect(math.absoluteDifference(5, 10)).toBe(5);
    });
  });
});
